@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool availabilityConfirmed;
    private bool submitSuccess;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    // Step 1 fields for partial validation
    private static readonly HashSet<string> step1Fields =
    [
        nameof(AppointmentModel.PatientName),
        nameof(AppointmentModel.Email),
        nameof(AppointmentModel.Phone),
        nameof(AppointmentModel.InsuranceProvider)
    ];

    protected override void OnInitialized()
    {
        editContext = new EditContext(model);
    }

    private async Task ProceedToStep2()
    {
        // Validate only step 1 fields
        editContext.Validate();
        var hasStep1Errors = editContext.GetValidationMessages()
            .Any(msg => step1Fields.Any(f =>
                editContext.GetValidationMessages(editContext.Field(f)).Contains(msg)));

        // Check each step 1 field individually
        bool step1Valid = !step1Fields
            .SelectMany(f => editContext.GetValidationMessages(editContext.Field(f)))
            .Any();

        if (!step1Valid)
            return;

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
            model.TimeSlot = null;
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;

        // Validate step 2 required fields locally first
        editContext.Validate();

        bool step2Valid = true;
        if (string.IsNullOrWhiteSpace(model.Doctor))
            step2Valid = false;
        if (!model.AppointmentDate.HasValue || model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(model.TimeSlot))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
            step2Valid = false;

        if (!step2Valid)
            return;

        isProcessing = true;

        try
        {
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                model.Email!,
                model.InsuranceProvider!,
                model.Doctor!,
                model.TimeSlot!);

            if (serverErrors.Count > 0)
            {
                // Map service field names to model field names
                var mappedErrors = new Dictionary<string, List<string>>();
                foreach (var (key, value) in serverErrors)
                {
                    var modelField = key switch
                    {
                        "email" => nameof(AppointmentModel.Email),
                        "doctor" => nameof(AppointmentModel.Doctor),
                        "timeSlot" => nameof(AppointmentModel.TimeSlot),
                        _ => key
                    };
                    mappedErrors[modelField] = value;
                }

                customValidator!.DisplayErrors(mappedErrors);
                return;
            }

            availabilityConfirmed = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        isProcessing = true;
        submitSuccess = false;

        try
        {
            // Simulate booking
            await Task.Delay(500);
            submitSuccess = true;

            // Reset form
            model = new();
            editContext = new EditContext(model);
            showStep2 = false;
            availabilityConfirmed = false;
            timeSlots = [];
        }
        finally
        {
            isProcessing = false;
        }
    }
}

