@rendermode InteractiveServer
@using sv_a1fe0fe836a94fccb6e3561f0b6e26c6.Models
@using sv_a1fe0fe836a94fccb6e3561f0b6e26c6.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h4>Step 1: Patient Information</h4>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
        <ValidationMessage For="() => model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="model.Email" />
        <ValidationMessage For="() => model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
        <ValidationMessage For="() => model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-control" @bind-Value="model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Continue to Step 2")
        </button>
    }

    @if (showStep2)
    {
        <hr />
        <h4>Step 2: Appointment Details</h4>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-control" @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Appointment Date</label>
            <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate" @bind:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-control" @bind-Value="model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
            <ValidationMessage For="() => model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Check Availability")
        </button>

        @if (availabilityConfirmed)
        {
            <button type="submit" class="btn btn-success" disabled="@isProcessing">
                @(isProcessing ? "Submitting..." : "Book Appointment")
            </button>
        }
    }

    @if (submitSuccess)
    {
        <div class="alert alert-success mt-3">Appointment booked successfully!</div>
    }
</EditForm>

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool availabilityConfirmed;
    private bool submitSuccess;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    // Step 1 fields for partial validation
    private static readonly HashSet<string> step1Fields =
    [
        nameof(AppointmentModel.PatientName),
        nameof(AppointmentModel.Email),
        nameof(AppointmentModel.Phone),
        nameof(AppointmentModel.InsuranceProvider)
    ];

    protected override void OnInitialized()
    {
        editContext = new EditContext(model);
    }

    private async Task ProceedToStep2()
    {
        // Validate only step 1 fields
        editContext.Validate();
        var hasStep1Errors = editContext.GetValidationMessages()
            .Any(msg => step1Fields.Any(f =>
                editContext.GetValidationMessages(editContext.Field(f)).Contains(msg)));

        // Check each step 1 field individually
        bool step1Valid = !step1Fields
            .SelectMany(f => editContext.GetValidationMessages(editContext.Field(f)))
            .Any();

        if (!step1Valid)
            return;

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
            model.TimeSlot = null;
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;

        // Validate step 2 required fields locally first
        editContext.Validate();

        bool step2Valid = true;
        if (string.IsNullOrWhiteSpace(model.Doctor))
            step2Valid = false;
        if (!model.AppointmentDate.HasValue || model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(model.TimeSlot))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
            step2Valid = false;

        if (!step2Valid)
            return;

        isProcessing = true;

        try
        {
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                model.Email!,
                model.InsuranceProvider!,
                model.Doctor!,
                model.TimeSlot!);

            if (serverErrors.Count > 0)
            {
                // Map service field names to model field names
                var mappedErrors = new Dictionary<string, List<string>>();
                foreach (var (key, value) in serverErrors)
                {
                    var modelField = key switch
                    {
                        "email" => nameof(AppointmentModel.Email),
                        "doctor" => nameof(AppointmentModel.Doctor),
                        "timeSlot" => nameof(AppointmentModel.TimeSlot),
                        _ => key
                    };
                    mappedErrors[modelField] = value;
                }

                customValidator!.DisplayErrors(mappedErrors);
                return;
            }

            availabilityConfirmed = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        isProcessing = true;
        submitSuccess = false;

        try
        {
            // Simulate booking
            await Task.Delay(500);
            submitSuccess = true;

            // Reset form
            model = new();
            editContext = new EditContext(model);
            showStep2 = false;
            availabilityConfirmed = false;
            timeSlots = [];
        }
        finally
        {
            isProcessing = false;
        }
    }
}

